import sympy

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def has_roots_mod_p(f, p):
    # Compute the Legendre symbol (p|f(x))
    # using the quadratic reciprocity law
    if p % 4 == 1:
        return sympy.little_a(f, p)
    else:
        return -sympy.little_a(f, p)

def little_a(f, p):
    # Compute the Legendre symbol (p|f(x))
    # using the quadratic reciprocity law
    if p % 4 == 1:
        return 1
    elif p % 4 == 3:
        return -1
    else:
        return 1

# Define the polynomial f(x) = x^2 + 3x + 3
f = sympy.sympify('x**2 + 3*x + 3')

# Check for roots mod p for odd primes p > 3
for p in range(7, 100, 2):  # Start from 7, as 5 is not a valid prime
    if is_prime(p):
        if has_roots_mod_p(f, p):
            print(f'p = {p} has roots mod p')
        else:
            print(f'p = {p} does not have roots mod p')

# Check for roots mod p for p ≡ 1 (mod 3)
for p in range(7, 100, 3):  # Start from 7, as 5 is not a valid prime
